scripts/cve_pack_enrich.py:
"""Aggregate actionable 'tips' for a CVE across every feed, deduped.

When the monitor flags a CVE, or `cve_pack run` finds a rule gap, these tips
tell the user what to do: the version to upgrade to, how urgent it is (actively
exploited, exploitation probability), and the authoritative remediation action.
Nothing here sends traffic; it only reads public feeds.
"""

import http.client
import urllib.error

from cve_pack_feeds import (
    epss,
    kev_catalog,
    nvd_cve,
    nvd_cwes,
    nvd_fixed_versions,
    osv_fixed_versions,
)


def kev_index(fetcher):
    """{cveID: entry} for fast membership, plus the catalog version/date."""
    catalog = kev_catalog(fetcher)
    index = {v["cveID"]: v for v in catalog["vulnerabilities"] if v.get("cveID")}
    return index, {"version": catalog["version"], "released": catalog["released"]}


def _dedupe(items, key):
    seen, out = set(), []
    for item in items:
        k = key(item)
        if k not in seen:
            seen.add(k)
            out.append(item)
    return out


def _kev_tip(entry):
    if not entry:
        return None
    notes = entry.get("notes", "") or ""
    refs = [
        u.strip()
        for u in notes.replace(",", ";").split(";")
        if u.strip().startswith("http")
    ]
    return {
        "listed": True,
        "date_added": entry.get("dateAdded"),
        "required_action": entry.get("requiredAction"),
        "due_date": entry.get("dueDate"),
        "known_ransomware": entry.get("knownRansomwareCampaignUse") == "Known",
        "references": refs,
    }


class FeedResults:
    """Record failed reads, including optional OSV aliases, without losing other feeds."""

    def __init__(self, fetcher):
        self.fetcher = fetcher
        self.errors = []

    def get_json(self, url):
        try:
            return self.fetcher.get_json(url)
        except (OSError, ValueError, http.client.HTTPException) as error:
            # OSV uses 404 for an identifier absent from its catalog.
            if (
                isinstance(error, urllib.error.HTTPError)
                and error.code == 404
                and url.startswith("https://api.osv.dev/v1/vulns/")
            ):
                return {}
            self.errors.append(
                {
                    "url": url,
                    "error": type(error).__name__,
                    "http_status": getattr(error, "code", None),
                }
            )
            raise OSError(f"Feed unavailable: {url}") from error


def tips(cve, *, fetcher, kev=None):
    """Aggregate tips for one CVE. `kev` is an optional (index, meta) from
    kev_index(); pass it when enriching many CVEs to avoid refetching KEV."""
    fetcher = FeedResults(fetcher)
    if kev is None:
        try:
            kev = kev_index(fetcher)
        except (OSError, ValueError):
            kev = None
    kev_entry = (kev[0] if kev else {}).get(cve)
    kev_tip = _kev_tip(kev_entry)

    try:
        cve_obj = nvd_cve(fetcher, cve)
    except (OSError, ValueError):
        cve_obj = None
    cwes = nvd_cwes(cve_obj)
    osv_entries, osv_refs = osv_fixed_versions(fetcher, cve)
    osv_entries = _dedupe(
        osv_entries, key=lambda e: (e["ecosystem"], e["package"], e["fixed"])
    )
    # OSV ecosystem fixes name the actual package; NVD CPE adds bundled-product
    # noise (firmware that ships the library), kept only as a capped fallback.
    cpe_entries = _dedupe(
        nvd_fixed_versions(cve_obj), key=lambda e: (e["package"], e["fixed"])
    )
    fixed = osv_entries + cpe_entries[:20]
    score, percentile = epss(fetcher, cve)

    references = _dedupe(
        [{"url": u} for u in osv_refs]
        + [
            {"url": r.get("url")}
            for r in (cve_obj or {}).get("references", [])
            if r.get("url")
        ]
        + [{"url": u} for u in (kev_tip["references"] if kev_tip else [])],
        key=lambda r: r["url"],
    )

    return {
        "cve": cve,
        "complete": not fetcher.errors,
        "feed_errors": fetcher.errors,
        "actively_exploited": bool(kev_tip) if kev is not None else None,
        "known_ransomware": bool(kev_tip and kev_tip["known_ransomware"])
        if kev is not None
        else None,
        "epss": None if score is None else {"score": score, "percentile": percentile},
        "cwes": cwes,
        "fixed_versions": fixed,
        "kev": kev_tip,
        "references": [r["url"] for r in references][:15],
        # Prefer the named-package (OSV) fixes for the one-line advice; CPE
        # firmware fallback is kept in fixed_versions but not dumped here.
        "advice": _advice(kev_tip, osv_entries or cpe_entries, score),
    }


def _advice(kev_tip, fixed, score):
    bits = []
    if kev_tip:
        bits.append("actively exploited (CISA KEV)")
        if kev_tip["known_ransomware"]:
            bits.append("used in ransomware")
        if kev_tip.get("due_date"):
            bits.append(f"CISA remediation due {kev_tip['due_date']}")
    if score is not None:
        bits.append(f"EPSS {score:.0%}")
    if fixed:
        where = ", ".join(sorted({f"{e['package']} {e['fixed']}" for e in fixed})[:4])
        bits.append(f"upgrade to {where}")
    else:
        bits.append(
            "no fixed version found in available feed data; consult the vendor advisory"
        )
    return "; ".join(bits)

scripts/cve_pack_feeds.py:
"""Read-only clients for the public vulnerability feeds the monitor uses.

All network access goes through a Fetcher, so tests inject a fixed mapping and
never touch the network. Live use is GET-only, bounded, with a short timeout.

Feeds (deduped by the enrich layer):
- CISA KEV      the actively-exploited catalog (primary trigger)
- NVD API 2.0   CWE weaknesses and affected/fixed version ranges (CPE)
- OSV           per-package 'fixed in' version, following GHSA aliases
- EPSS (FIRST)  probability a CVE will be exploited (prioritization)
"""

import json
import urllib.request

KEV_URL = "https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json"
NVD_URL = "https://services.nvd.nist.gov/rest/json/cves/2.0"
OSV_VULN_URL = "https://api.osv.dev/v1/vulns"
EPSS_URL = "https://api.first.org/data/v1/epss"
USER_AGENT = "mockforge-cve-pack-monitor (+https://mockforge.dev)"
MAX_BYTES = 8 * 1024 * 1024


class Fetcher:
    """Bounded GET -> parsed JSON. Pass `responses` (a {url_prefix: object}
    mapping, values may be Exceptions) to stub the network in tests."""

    def __init__(self, timeout=15, responses=None):
        self.timeout = timeout
        self.responses = responses

    def get_json(self, url):
        if self.responses is not None:
            for prefix, value in self.responses.items():
                if url.startswith(prefix):
                    if isinstance(value, Exception):
                        raise value
                    return value
            raise KeyError(f"no stubbed response for {url}")
        request = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
        with urllib.request.urlopen(request, timeout=self.timeout) as response:
            return json.loads(response.read(MAX_BYTES))


def kev_catalog(fetcher):
    """The KEV catalog as {version, released, vulnerabilities: [...]}."""
    doc = fetcher.get_json(KEV_URL)
    return {
        "version": doc.get("catalogVersion"),
        "released": doc.get("dateReleased"),
        "vulnerabilities": doc.get("vulnerabilities", []),
    }


def nvd_cve(fetcher, cve):
    """The NVD `cve` object for one id, or None."""
    doc = fetcher.get_json(f"{NVD_URL}?cveId={cve}")
    items = doc.get("vulnerabilities") or []
    return items[0]["cve"] if items else None


def nvd_cwes(cve_obj):
    out = []
    for weakness in (cve_obj or {}).get("weaknesses", []):
        for desc in weakness.get("description", []):
            value = desc.get("value", "")
            if value.startswith("CWE-") and value not in out:
                out.append(value)
    return out


def nvd_fixed_versions(cve_obj):
    """Fixed versions implied by CPE `versionEndExcluding` across configs."""
    out = []
    for config in (cve_obj or {}).get("configurations", []):
        for node in config.get("nodes", []):
            for match in node.get("cpeMatch", []):
                end = match.get("versionEndExcluding")
                if not end:
                    continue
                parts = match.get("criteria", "").split(":")
                product = parts[4] if len(parts) > 4 else "?"
                out.append({"ecosystem": "cpe", "package": product, "fixed": end})
    return out


def _affected_fixed(vuln):
    out = []
    for affected in (vuln or {}).get("affected", []):
        pkg = affected.get("package", {})
        for rng in affected.get("ranges", []):
            # Skip GIT ranges: their 'fixed' is a commit hash, not a version.
            if rng.get("type") == "GIT":
                continue
            for event in rng.get("events", []):
                if "fixed" in event and pkg.get("name"):
                    out.append(
                        {
                            "ecosystem": pkg.get("ecosystem", "?"),
                            "package": pkg["name"],
                            "fixed": event["fixed"],
                        }
                    )
    return out


def osv_fixed_versions(fetcher, cve):
    """Per-package 'fixed in' versions from OSV, following GHSA aliases.

    Returns (entries, references). The CVE record and each aliased GHSA record
    are merged; the enrich layer dedupes against the other feeds."""
    try:
        root = fetcher.get_json(f"{OSV_VULN_URL}/{cve}")
    except (OSError, KeyError, ValueError):
        return [], []
    entries = _affected_fixed(root)
    references = [r.get("url") for r in root.get("references", []) if r.get("url")]
    for alias in root.get("aliases", []):
        if not alias.startswith("GHSA-"):
            continue
        try:
            record = fetcher.get_json(f"{OSV_VULN_URL}/{alias}")
        except (OSError, KeyError, ValueError):
            continue
        entries.extend(_affected_fixed(record))
        references.extend(
            r.get("url") for r in record.get("references", []) if r.get("url")
        )
    return entries, references


def epss(fetcher, cve):
    """(score, percentile) floats for a CVE, or (None, None)."""
    try:
        doc = fetcher.get_json(f"{EPSS_URL}?cve={cve}")
    except (OSError, KeyError, ValueError):
        return None, None
    data = doc.get("data") or []
    if not data:
        return None, None
    try:
        return float(data[0]["epss"]), float(data[0]["percentile"])
    except (KeyError, ValueError, TypeError):
        return None, None

scripts/cve_pack_monitor.py:
"""Monitor public vulnerability feeds and emit candidate CVE rule packs.

Primary trigger is CISA KEV (actively exploited). Each candidate is enriched
with tips from NVD, OSV and EPSS (deduped), triaged to web-/WAF-relevant CWEs,
and — when a drafter command is configured — given a schema-validated signature
draft. Without a drafter it emits an enriched stub to fill. CVEs already covered
by a profile are skipped, and every CVE is keyed once across all sources.

The monitor only reads feeds and writes candidate files; it sends no traffic and
opens no pull request. Review a candidate, then run it with cve_pack.py.
"""

import argparse
import datetime
import json
from pathlib import Path

from cve_pack_draft import CommandDrafter, draft_profile
from cve_pack_enrich import kev_index, tips
from cve_pack_feeds import Fetcher
from cve_pack_profile import SCHEMA_VERSION
from cve_pack_triage import rank, web_relevant

SKELETON_SIGNATURE = {
    "method": "GET",
    "query": {},
    "headers": {"x-REPLACE-with-the-rule-signature-header": "marker"},
}


def existing_cves(dirs):
    """CVE ids already covered by a profile.json under any of `dirs`."""
    covered = set()
    for d in dirs:
        for path in Path(d).rglob("profile.json"):
            try:
                covered.add(json.loads(path.read_text())["cve"])
            except (OSError, ValueError, KeyError):
                continue
    return covered


def _advisory_text(kev_entry):
    parts = [
        kev_entry.get("vulnerabilityName", ""),
        kev_entry.get("shortDescription", ""),
        kev_entry.get("requiredAction", ""),
    ]
    return "\n".join(p for p in parts if p)


def _stub(cve, title, references):
    return {
        "schema_version": SCHEMA_VERSION,
        "cve": cve,
        "title": title[:200] or cve,
        "references": references[:10] or ["https://nvd.nist.gov/vuln/detail/" + cve],
        "route": "/REPLACE/with/the/guarded/route",
        "signature": dict(SKELETON_SIGNATURE),
        "expect": {"blocked_status": 403, "origin": "absent"},
        "controls": [
            {
                "id": "benign",
                "query": {},
                "headers": {},
                "expect": {"status": 200, "origin": "seen"},
            }
        ],
    }


def candidates(fetcher, *, since=None, limit=50, drafter=None, known=()):
    """Enriched candidate dicts for KEV CVEs, most-urgent first.

    Triage and ordering use the cheap per-entry KEV fields (its own `cwes`, the
    ransomware flag, dateAdded), so only the top `limit` web-relevant CVEs are
    enriched with per-CVE NVD/OSV/EPSS calls. Entries without KEV CWEs are not
    triaged in and would need a hand-authored profile."""
    index, meta = kev_index(fetcher)
    covered = set(known)
    pool = []
    for cve, entry in index.items():
        if cve in covered:
            continue
        if since and (entry.get("dateAdded") or "") < since:
            continue
        if not web_relevant(entry.get("cwes")):
            continue
        pool.append((cve, entry))
    # Cheap ordering: ransomware-linked first, then most recently added.
    pool.sort(
        key=lambda r: (
            r[1].get("knownRansomwareCampaignUse") == "Known",
            r[1].get("dateAdded", ""),
        ),
        reverse=True,
    )

    out = []
    for cve, entry in pool[:limit]:
        t = tips(cve, fetcher=fetcher, kev=(index, meta))
        title = entry.get("vulnerabilityName") or entry.get("shortDescription") or cve
        references = t["references"]
        candidate = {
            "cve": cve,
            "title": title[:200],
            "rank": round(rank(t), 3),
            "tips": t,
            "status": "stub",
            "reason": None,
            "profile": _stub(cve, title, references),
        }
        if drafter is not None:
            profile, reason = draft_profile(
                cve,
                title=title[:200],
                references=references[:10]
                or ["https://nvd.nist.gov/vuln/detail/" + cve],
                cwes=t["cwes"],
                advisory_text=_advisory_text(entry),
                drafter=drafter,
            )
            if profile is not None:
                candidate.update(status="drafted", profile=profile)
            else:
                candidate.update(status="needs-review", reason=reason)
        out.append(candidate)
        if len(out) >= limit:
            break
    return {"kev_version": meta["version"], "generated": _now(), "candidates": out}


def _now():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def write_candidates(result, out_dir):
    """Write each candidate's profile and tips under out_dir/<cve>/."""
    base = Path(out_dir)
    for c in result["candidates"]:
        d = base / c["cve"]
        d.mkdir(parents=True, exist_ok=True)
        name = (
            "profile.json"
            if c["status"] in ("drafted", "stub")
            else "profile.needs-review.json"
        )
        (d / name).write_text(json.dumps(c["profile"], indent=2) + "\n")
        (d / "tips.json").write_text(json.dumps(c["tips"], indent=2) + "\n")


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--out-dir", required=True, help="where candidate packs are written"
    )
    parser.add_argument("--report", help="write the run report JSON here")
    parser.add_argument("--since", help="only KEV entries dateAdded >= YYYY-MM-DD")
    parser.add_argument("--limit", type=int, default=50)
    parser.add_argument(
        "--known-dir",
        action="append",
        default=[],
        help="profiles already covered (repeatable); these CVEs are skipped",
    )
    parser.add_argument(
        "--drafter-cmd",
        help="command that reads a JSON context on stdin and prints a JSON "
        "signature proposal; its output is schema-validated before use",
    )
    parser.add_argument("--timeout", type=float, default=20)
    args = parser.parse_args(argv)
    try:
        if not 0 < args.timeout <= 60 or not 1 <= args.limit <= 500:
            raise ValueError("timeout must be 0..60s; limit must be 1..500")
        fetcher = Fetcher(timeout=args.timeout)
        drafter = CommandDrafter(args.drafter_cmd) if args.drafter_cmd else None
        known = existing_cves(args.known_dir) if args.known_dir else set()
        result = candidates(
            fetcher, since=args.since, limit=args.limit, drafter=drafter, known=known
        )
        write_candidates(result, args.out_dir)
        if args.report:
            summary = {
                "kev_version": result["kev_version"],
                "generated": result["generated"],
                "candidates": [
                    {k: c[k] for k in ("cve", "title", "rank", "status", "reason")}
                    | {"advice": c["tips"]["advice"]}
                    for c in result["candidates"]
                ],
            }
            Path(args.report).write_text(json.dumps(summary, indent=2) + "\n")
    except (ValueError, OSError) as exc:
        parser.error(str(exc))
    for c in result["candidates"]:
        print(f"{c['cve']} [{c['status']}] rank={c['rank']}: {c['tips']['advice']}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

scripts/cve_pack_profile.py:
"""Declarative CVE rule-test profile: strict schema that admits only inert
markers, so a profile can describe a WAF/LB rule's signature but can never
carry a working payload.

A profile names the route a rule guards and the signature tokens the rule
matches on (header and query-parameter *names*, with harmless marker
*values*), plus benign controls and the expected rule outcome. It is consumed
by cve_pack.py to drive the same canary -> supplied-LB -> owned-recorder flow
that security_rule_test_pack.py uses, and by cve_pack_server.py to emit a
MockForge mock of the guarded route.

Safety is structural, not advisory:
- values are constrained to `[A-Za-z0-9_.:-]`, so they cannot contain spaces,
  quotes, slashes, angle brackets, `;`, `|`, `&`, `$`, `{`, `}`, `(`, `)`,
  `=`, `%` or backslashes. Command/template/markup/traversal payloads cannot be
  expressed.
- there is no request-body field anywhere; the schema rejects unknown keys.
- only GET is allowed, mirroring the bounded transport.
"""

import json
import re
from pathlib import Path

SCHEMA_VERSION = 1
CVE_ID = re.compile(r"^CVE-\d{4}-\d{4,}$")
ROUTE = re.compile(r"^/[A-Za-z0-9/_.\-]{0,200}$")
HEADER_NAME = re.compile(r"^[A-Za-z0-9\-]{1,64}$")
QUERY_KEY = re.compile(r"^[A-Za-z0-9_.\-]{1,64}$")
CONTROL_ID = re.compile(r"^[a-z0-9][a-z0-9\-]{0,39}$")
# The one structural guarantee: marker values are inert tokens, never payloads.
MARKER = re.compile(r"^[A-Za-z0-9_.:\-]{1,128}$")
MAX_CONTROLS = 5
MAX_TOKENS = 8
CORRELATION_KEY = "__mockforge_correlation"
CORRELATION_HEADER = "X-Mockforge-Correlation"


class ProfileError(ValueError):
    """A profile that is malformed or would carry anything but inert markers."""


def _tokens(value, kind, keyre):
    if not isinstance(value, dict):
        raise ProfileError(f"{kind} must be an object of name -> marker value")
    if len(value) > MAX_TOKENS:
        raise ProfileError(f"{kind} allows at most {MAX_TOKENS} entries")
    out = {}
    for key, marker in value.items():
        if not isinstance(key, str) or not keyre.match(key):
            raise ProfileError(f"{kind} name {key!r} is not an allowed identifier")
        if key.lower() in (CORRELATION_KEY, CORRELATION_HEADER.lower()):
            raise ProfileError(f"{kind} name {key!r} is reserved for correlation")
        if not isinstance(marker, str) or not MARKER.match(marker):
            raise ProfileError(
                f"{kind} value for {key!r} must be an inert marker matching "
                f"[A-Za-z0-9_.:-]{{1,128}} (no payloads, spaces or metacharacters)"
            )
        out[key] = marker
    return out


def _signature(sig):
    if not isinstance(sig, dict) or set(sig) - {"method", "query", "headers"}:
        raise ProfileError("signature allows only method, query and headers")
    if sig.get("method", "GET") != "GET":
        raise ProfileError("only GET signatures are supported")
    query = _tokens(sig.get("query", {}), "signature.query", QUERY_KEY)
    headers = _tokens(sig.get("headers", {}), "signature.headers", HEADER_NAME)
    if not query and not headers:
        raise ProfileError("signature needs at least one query or header token")
    return {"method": "GET", "query": query, "headers": headers}


def _expect(expect, *, blocked):
    allowed = {"blocked_status", "origin"} if blocked else {"status", "origin"}
    if not isinstance(expect, dict) or set(expect) != allowed:
        raise ProfileError(f"expect requires exactly {sorted(allowed)}")
    status = expect["blocked_status"] if blocked else expect["status"]
    if type(status) is not int:
        raise ProfileError("expect status must be an integer")
    if blocked:
        if not 400 <= status <= 599:
            raise ProfileError("a blocked_status must be 400..599")
        if expect["origin"] != "absent":
            raise ProfileError("a blocked signature must expect origin 'absent'")
    else:
        if not 200 <= status <= 399:
            raise ProfileError("a control status must be 200..399")
        if expect["origin"] != "seen":
            raise ProfileError("a benign control must expect origin 'seen'")
    return {"status": status, "origin": expect["origin"]}


def _control(control):
    if not isinstance(control, dict) or set(control) - {
        "id",
        "query",
        "headers",
        "expect",
    }:
        raise ProfileError("control allows only id, query, headers and expect")
    cid = control.get("id")
    if not isinstance(cid, str) or not CONTROL_ID.match(cid):
        raise ProfileError("control id must be a short lower-case slug")
    return {
        "id": cid,
        "query": _tokens(control.get("query", {}), "control.query", QUERY_KEY),
        "headers": _tokens(control.get("headers", {}), "control.headers", HEADER_NAME),
        "expect": _expect(control.get("expect"), blocked=False),
    }


def validate(profile):
    """Return a normalized profile or raise ProfileError. Pure, no I/O."""
    if not isinstance(profile, dict):
        raise ProfileError("profile must be a JSON object")
    allowed = {
        "schema_version",
        "cve",
        "title",
        "references",
        "route",
        "signature",
        "expect",
        "controls",
    }
    if set(profile) != allowed:
        raise ProfileError(f"profile requires exactly {sorted(allowed)}")
    if profile["schema_version"] != SCHEMA_VERSION:
        raise ProfileError("unsupported schema_version")
    if not isinstance(profile["cve"], str) or not CVE_ID.match(profile["cve"]):
        raise ProfileError("cve must look like CVE-YYYY-NNNN")
    if not isinstance(profile["title"], str) or not 1 <= len(profile["title"]) <= 200:
        raise ProfileError("title must be 1..200 characters")
    refs = profile["references"]
    if not isinstance(refs, list) or not 1 <= len(refs) <= 10:
        raise ProfileError("references must list 1..10 vendor/advisory URLs")
    for ref in refs:
        if not isinstance(ref, str) or not ref.startswith("https://"):
            raise ProfileError("each reference must be an https URL")
    if not isinstance(profile["route"], str) or not ROUTE.match(profile["route"]):
        raise ProfileError("route must be an absolute path with no query or '..'")
    if ".." in profile["route"]:
        raise ProfileError("route must not contain '..'")
    signature = _signature(profile["signature"])
    if (
        profile["title"] == "One-line description of the guarded weakness"
        or "https://vendor.example/advisory" in refs
        or profile["route"] == "/the/guarded/route"
        or "x-example-signature-header" in signature["headers"]
    ):
        raise ProfileError(
            "unfinished template: replace title, references, route and signature from the advisory; new does not simulate a CVE"
        )
    controls = profile["controls"]
    if not isinstance(controls, list) or not 1 <= len(controls) <= MAX_CONTROLS:
        raise ProfileError(f"controls must list 1..{MAX_CONTROLS} benign cases")
    seen = set()
    norm_controls = []
    for control in controls:
        c = _control(control)
        if c["id"] in seen:
            raise ProfileError("duplicate control id")
        seen.add(c["id"])
        norm_controls.append(c)
    return {
        "schema_version": SCHEMA_VERSION,
        "cve": profile["cve"],
        "title": profile["title"],
        "references": list(refs),
        "route": profile["route"],
        "signature": signature,
        "expect": _expect(profile["expect"], blocked=True),
        "controls": norm_controls,
    }


def load(path):
    return validate(json.loads(Path(path).read_text()))


def _case_path(route, query):
    if not query:
        return route
    pairs = "&".join(f"{k}={v}" for k, v in query.items())
    return route + ("&" if "?" in route else "?") + pairs


def cases(profile):
    """Yield (id, path, headers, expect, kind) for the signature then controls.

    kind is 'signature' or 'control'. Paths and headers hold only the profile's
    inert markers; cve_pack.py adds the correlation token at send time.
    """
    sig = profile["signature"]
    yield (
        profile["cve"],
        _case_path(profile["route"], sig["query"]),
        dict(sig["headers"]),
        profile["expect"],
        "signature",
    )
    for control in profile["controls"]:
        yield (
            control["id"],
            _case_path(profile["route"], control["query"]),
            dict(control["headers"]),
            control["expect"],
            "control",
        )

