"""Turn a CVE profile into a MockForge mock of the guarded route.

The mock makes `mockforge serve` answer the profile's route with a small,
fixed 200 body, so a load balancer in front of it sees a target that *looks*
like the guarded application. MockForge serves canned responses only: none of
the vulnerable code runs, and the spec carries no payload. This is a
convenience for manually exploring a rule against a realistic origin; the
automated `cve_pack.py run` uses the owned correlation recorder instead.
"""

from cve_pack_profile import validate


def to_openapi(profile):
    """Return an OpenAPI 3.0.3 mock document for the profile's route."""
    profile = validate(profile)
    body = {"receiver": "mockforge-cve-pack", "cve": profile["cve"]}
    return {
        "openapi": "3.0.3",
        "info": {
            "title": f"{profile['cve']} rule-test mock",
            "version": "1.0.0",
            "description": (
                "Mocks the guarded route so a load balancer sees a realistic "
                "origin. Canned response only; no vulnerable behavior is run."
            ),
        },
        "paths": {
            profile["route"]: {
                "get": {
                    "operationId": "cvePackGuardedRoute",
                    "responses": {
                        "200": {
                            "description": "Mock origin reached; no exploit simulated",
                            "content": {
                                "application/json": {
                                    "schema": {
                                        "type": "object",
                                        "required": ["receiver", "cve"],
                                        "properties": {
                                            "receiver": {"type": "string"},
                                            "cve": {"type": "string"},
                                        },
                                    },
                                    "example": body,
                                }
                            },
                        }
                    },
                }
            }
        },
    }

scripts/security_rule_pack_config.py:
"""Closed safe canary definitions and strict expectation schema validation."""

import json
from pathlib import Path


CASES = {
    "normal-control": ("/security-rule-probe", {}),
    "nextjs-benign": ("/security-rule-probe", {"X-Client-Note": "middleware"}),
    "nextjs-header": (
        "/security-rule-probe",
        {"x-middleware-subrequest": "middleware:" * 4 + "middleware"},
    ),
    "camel-benign": ("/security-rule-probe?beanMethodName=mockforgeCanary", {}),
    "camel-parameter": ("/security-rule-probe?cAmelBeanMethodName=mockforgeCanary", {}),
    "camel-header": (
        "/security-rule-probe",
        {"cAmelBeanMethodName": "mockforgeCanary"},
    ),
}


CONTROLS = {"normal-control", "nextjs-benign", "camel-benign"}


def load_pack(path):
    pack = json.loads(Path(path).read_text())
    if not isinstance(pack, dict) or set(pack) != {"schema_version", "cases"}:
        raise ValueError("pack requires only schema_version and cases")
    if type(pack["schema_version"]) is not int or pack["schema_version"] != 1:
        raise ValueError("unsupported schema_version")
    cases = pack["cases"]
    if not isinstance(cases, list) or not 5 <= len(cases) <= len(CASES):
        raise ValueError("pack requires five supported cases and optional camel-header")
    seen = set()
    for case in cases:
        if not isinstance(case, dict) or set(case) != {"id", "status", "origin"}:
            raise ValueError("case requires only id, status and origin")
        name, status, origin = case["id"], case["status"], case["origin"]
        if not isinstance(name, str) or name not in CASES or name in seen:
            raise ValueError("unknown or duplicate case id")
        seen.add(name)
        if type(status) is not int or not 200 <= status <= 599:
            raise ValueError("status must be an integer from 200 to 599")
        if origin not in ("seen", "absent"):
            raise ValueError("origin must be seen or absent")
        if name in CONTROLS and (status != 200 or origin != "seen"):
            raise ValueError("benign controls require 200 and origin seen")
        if origin == "absent" and status < 400:
            raise ValueError("rejection requires an explicit error status")
    if not set(CASES) - {"camel-header"} <= seen:
        raise ValueError("all supported probes and benign controls are required")
    return cases

scripts/security_rule_pack_evidence.py:
"""Correlate receiver observations and conservatively classify rule evidence."""

import http.client
import time
import uuid
from security_rule_pack_config import CASES


def observe(name, *, run_id, url, observations, lock, timeout, window, send):
    token = run_id + "-" + uuid.uuid4().hex
    path, headers = CASES[name]
    path += ("&" if "?" in path else "?") + "__mockforge_correlation=" + token
    headers = {**headers, "X-Mockforge-Correlation": token}
    try:
        status = send(url, path, headers, timeout)
        error = None
    except (OSError, http.client.HTTPException) as exc:
        status, error = None, type(exc).__name__
    time.sleep(window)
    with lock:
        records = list(observations.get(token, []))
    # Require exact request path, one observation, and matching probe headers.
    valid = len(records) == 1 and records[0]["path"] == path
    if valid:
        valid = all(
            [value for key, value in records[0]["headers"] if key.lower() == k.lower()]
            == [v]
            for k, v in headers.items()
        )
    return status, error, records, valid, token


def classify(case, status, error, records, valid, healthy):
    """Decide only the evidence supported verdict; absent data never proves blocking."""
    result = {"rule_behavior": "inconclusive"}
    if error or (records and not valid):
        result["reason"] = error or "origin correlation unavailable"
    elif status != case["status"]:
        result.update(rule_behavior="fail", reason="explicit status assertion mismatch")
    elif not healthy:
        result["reason"] = "flanking controls could not corroborate origin reachability"
    elif case["origin"] == "seen" and not records:
        result["reason"] = "expected origin observation missing"
    elif case["origin"] == "absent" and records:
        result.update(
            rule_behavior="fail", reason="rejected response still reached origin"
        )
    else:
        result.update(
            rule_behavior="pass", reason="status and bounded origin assertion agree"
        )
    return result
